/**
 * POTY Loader gadget
 * Keeps the impact to other users working on Commons as small as possible.
 * 
 */
(function() {
	if ( !( /^Commons(?:_talk)?:Picture_of_the_Year/.test( mw.config.get('wgPageName') ) ||
		/^Template:POTY2022/.test( mw.config.get('wgPageName') ) ) ) return;

	mw.loader.load('ext.gadget.POTYEnhancements.core');
}());

(function() {
	var title = $.trim($('#mw-nstab').data('nstab'));
	if ( title !== '' ) {
		$('#ca-nstab-' + ( mw.config.get('wgCanonicalNamespace').toLowerCase() || 'main' )).find('a').text(title);
	}


	if ( $('#poty-gallery-heading').length || $('#poty-hide-page-stuff').length ) {
		mw.util.addCSS('#firstHeading, #siteSub, #catlinks { display: none; }');
	}

	$('#com-my-poty-panel-container').show();

	window.potyconfig = {
		startDate: '2023-04-17T00:00:00Z'
	};		
}());
